python3 - <<'PY'
import json
r=json.load(open('/workspace/runtime_context.json'))
print('TOP KEYS', list(r))
for k,v in r.items():
 if k not in ['context','study_schema']: print(k, json.dumps(v))
c=r['context']; print('CONTEXT KEYS', list(c))
for k,v in c.items():
 if k"'!='"'history': print(k,json.dumps(v)[:26000])
print('HISTORY SUMMARY')
for h in c['history']:
 print(json.dumps({k:v for k,v in h.items() if k not in ['validation','config','candidate_diagnostics']},ensure_ascii=False))
 print('CONFIG',json.dumps(h.get('config',{})))
 print('METRICS',json.dumps(h.get('validation',{}))[:2700])
PY"

